def check(arr, mean, n):
	sum = 0
	for i in range(len(arr)):
		sum += arr[i]
	allowed_operations = n * mean - sum
	if allowed_operations < 0:
		return -1
	required_operations = 0
	for i in range((n - 1) // 2, n):
		required_operations += max(0, mean - arr[i])
	if required_operations > allowed_operations:
		return -1
	else:
		return allowed_operations
for i in range(int(input())):
	N = int(input())
	arr = [int(x) for x in input().split()]
	arr = sorted(arr)
	l = arr[(len(arr) - 1) // 2]
	r = arr[len(arr) - 1]
	ans = -1
	n = len(arr)
	while l <= r:
		mid = (l + r) // 2
		minOp = check(arr, mid, n)
		if minOp != -1:
			ans = minOp
			r = mid - 1
		else:
			l = mid + 1
	print(ans)
